{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Chrysin, a polyphenolic flavone with multiple phenolic OH groups and an aromatic heterocycle, has an estimated oral bioavailability of only 0.003–0.02% in healthy volunteers after a 400 mg oral dose, directly supporting a low-F outcome for the query's phenolic/heteroaromatic acid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Baicalein, a free flavone with three phenolic OH groups, is reported to have low oral bioavailability in humans, consistent with poor absorption and metabolic instability of polyphenolic compounds similar to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Aniracetam has extremely low oral bioavailability in humans due to rapid first-pass metabolism; despite structural differences, its high assay-transfer score indicates that a low-F outcome is applicable to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Acamprosate, an ionizable carboxylic acid-containing drug, is poorly absorbed with an average oral bioavailability of about 11% under fasting conditions, directly supporting low F for the query's ionized carboxylic acid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Rebamipide, an acidic drug containing a carboxylic acid and polar aromatic groups, has a human oral bioavailability under 10%, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Aspirin in solution has a reported absolute bioavailability of 65–75% in humans, which is contradictory to a low-F prediction; however, aspirin is a much smaller, less polar carboxylic acid and its high absorption does not overcome the consistent low-F evidence from more transferable analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low oral bioavailability (<20%). The query is a fully ionized, high-TPSA, sp3-free carboxylic acid with phenolic and heteroaromatic groups; multiple high-transfer human analogues with similar acidic/phenolic/heteroaromatic features show very low F (0.003–13%). The only contradictory high-F evidence (aspirin) comes from a much smaller, less polar molecule and is outweighed.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule itself.",
    "Aspirin evidence is mixed because formulation and measurement of parent vs total salicylate affect reported F; its relevance to the query is limited by structural differences.",
    "Potential active transport, efflux, or metabolic pathways for the query are not directly characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

